            "",
            "Message:",
            request.Message.Trim()),
        IsBodyHtml = false
    };
    message.To.Add("sales@sgsoftech.in");
    message.ReplyToList.Add(new MailAddress(replyAddress!.Address, request.FullName.Trim()));

    using var smtpClient = new SmtpClient(options.Host, options.Port)
    {
        EnableSsl = options.EnableSsl,
        DeliveryMethod = SmtpDeliveryMethod.Network,
        Timeout = 15000,
        Credentials = new NetworkCredential(options.Username, options.Password)
    };

    try
    {
        await smtpClient.SendMailAsync(message, cancellationToken);
        return Results.Ok(new { message = "Your enquiry has been sent to sales@sgsoftech.in." });
    }
    catch (SmtpException exception)
    {
        logger.LogError(exception, "SMTP delivery failed for a website enquiry.");
        return Results.Problem(
